            if (entry.entryType === 'resource' && entry.responseStatus >= 400) {
                // Extract just the filename from the full URL
                const urlParts = entry.name.split('/');
                const filename = urlParts[urlParts.length - 1];

                const message = `Resource failed to load (${entry.responseStatus}): ${filename}`;

                window.parent.postMessage(
                    {
                        action: 'codeError',
                        content: {
                            message: message,
                            source: entry.name,
                            lineNumber: 0,
                            columnNumber: 0,
                            stack: `Failed to load resource from: ${entry.name}\nStatus: ${entry.responseStatus || 'Network Error'}`,
                            errorName: 'ResourceLoadError',
                            fullError: `${message}\nURL: ${entry.name}`,
                        },
                    },
                    '*',
                );
            }
        }
    });

    observer.observe({ entryTypes: ['resource'] });
}

class RosebudOGP {
    async submitPoints(points = 0) {
        const TIMEOUT_DURATION = 150000;

        return new Promise((resolve, reject) => {
            const requestId = self.crypto.randomUUID();
            const handleMessage = (event) => {
                const { data } = event;
                if (data.requestId === requestId) {
                    window.removeEventListener('message', handleMessage);
                    clearTimeout(timeoutId);
                    if (data.error) {
                        reject(new Error(data.error));
                    } else {
                        resolve(data.content.message);
                    }
                }
            };

            window.addEventListener('message', handleMessage);

            window.parent.postMessage(
                {
                    action: 'ogpSubmitPoints',
                    points: points,
                    requestId: requestId,
                },
                '*',
            );

            const timeoutId = setTimeout(() => {
                window.removeEventListener('message', handleMessage);
                reject(new Error('Request timed out'));
            }, TIMEOUT_DURATION);
        });
    }
}

window.RosebudOGP = new RosebudOGP();

