];
const DISCORD_GRADE_RANK = { S: 0, A: 1, B: 2, C: 3 };
const DISCORD_GRADE_RESONANCE = { S: 10, A: 6, B: 3, C: 0 };
const DISCORD_GRADE_COLORS = { S: '#ffe09a', A: '#a8f0ca', B: '#9cecff', C: '#ff9cae' };

