// The Midnight Sessions: Echoes — vertical bullet-hell
const W = 720;
const H = 1080;
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = W;
canvas.height = H;

function resize() {
  const s = Math.min(window.innerWidth / W, window.innerHeight / H);
  canvas.style.width = `${W * s}px`;
  canvas.style.height = `${H * s}px`;
}
window.addEventListener('resize', resize);
resize();

const SESSION_BACKGROUNDS = [
  'assets/session-bg-happy-times.webp',
  'assets/session-bg-long-ago.webp',
  'assets/session-bg-haunted.webp',
  'assets/session-bg-burnt-letters.webp',
  'assets/session-bg-desolation.webp',
  'assets/session-bg-midnight-rain.webp',
  'assets/session-bg-myriad.webp',
  'assets/session-bg-owls.webp',
  'assets/session-bg-waltz-garden.webp',
  'assets/session-bg-eternal-sleep.webp',
].map((src) => {
  const image = new Image();
  image.src = src;
  return image;
});
const echoSprite = new Image();
echoSprite.src = 'assets/echo-spirit.webp';
const echoAwakenedSprite = new Image();
echoAwakenedSprite.src = 'assets/echo-veil-awakening.webp';
const echoQueenSprite = new Image();
echoQueenSprite.src = 'assets/echo-midnight-queen.webp';
function removeHorizontalSpriteStreaks(image) {
  image.addEventListener('load', () => {
    if (!image.naturalWidth || !image.naturalHeight) return;
    const scratch = document.createElement('canvas');
    scratch.width = image.naturalWidth;
    scratch.height = image.naturalHeight;
    const scratchContext = scratch.getContext('2d', { willReadFrequently: true });
    if (!scratchContext) return;
    scratchContext.drawImage(image, 0, 0);
    let pixels;
    try {
      pixels = scratchContext.getImageData(0, 0, scratch.width, scratch.height);
    } catch (error) {
      return;
    }

    const { data, width, height } = pixels;
    const remove = new Uint8Array(width * height);
    const scanStart = Math.floor(width * 0.58);
    const minRun = Math.max(20, Math.floor(width * 0.045));
    for (let y = 0; y < height; y++) {
      let runStart = -1;
      let baseR = 0;
      let baseG = 0;
      let baseB = 0;
      const finishRun = (end) => {
        if (runStart >= 0 && end - runStart >= minRun) {
          for (let x = runStart; x < end; x++) remove[y * width + x] = 1;
        }
        runStart = -1;
      };
      for (let x = scanStart; x <= width; x++) {
        const offset = (y * width + x) * 4;
        const r = x < width ? data[offset] : 0;
        const g = x < width ? data[offset + 1] : 0;
        const b = x < width ? data[offset + 2] : 0;
        const alpha = x < width ? data[offset + 3] : 0;
        const brightest = Math.max(r, g, b);
        const darkest = Math.min(r, g, b);
        const neutral = x < width && alpha > 18 && brightest - darkest < 38 && brightest > 32 && darkest < 238;
        const matchesRun = neutral && (runStart < 0 || (Math.abs(r - baseR) < 24 && Math.abs(g - baseG) < 24 && Math.abs(b - baseB) < 24));
        if (!matchesRun) {
          finishRun(x);
          if (!neutral) continue;
        }
        if (runStart < 0) {
          runStart = x;
          baseR = r;
          baseG = g;
          baseB = b;
        }
      }
    }
    for (let i = 0; i < remove.length; i++) {
      if (!remove[i]) continue;
      const offset = i * 4;
      data[offset] = 0;
      data[offset + 1] = 0;
      data[offset + 2] = 0;
      data[offset + 3] = 0;
    }
    scratchContext.putImageData(pixels, 0, 0);
    image.src = scratch.toDataURL('image/webp', 0.94);
  }, { once: true });
}

const echoOutfitSprites = {
  rose: new Image(),
  midnight: new Image(),
  frost: new Image(),
};
Object.values(echoOutfitSprites).forEach(removeHorizontalSpriteStreaks);
echoOutfitSprites.rose.src = 'assets/echo-rose-sonata-clean.webp';
echoOutfitSprites.midnight.src = 'assets/echo-midnight-constellation-clean.webp';
echoOutfitSprites.frost.src = 'assets/echo-frosted-songbird-clean.webp';
const enemySprites = [
  'assets/discord-raven.webp',
  'assets/discord-wraith.webp',
  'assets/discord-moth.webp',
  'assets/discord-glass-stag.webp',
  'assets/discord-serpent.webp',
  'assets/discord-jellyfish.webp',
].map((src) => {
  const image = new Image();
  image.src = src;
  return image;
});
const ENEMY_TYPES = [
  { name: 'DISCORD RAVEN', color: '#ff718b', glyph: '♟', hp: 1, radius: 28 },
  { name: 'VEILED WRAITH', color: '#ec83ff', glyph: '◈', hp: 1.08, radius: 28 },
  { name: 'THORN MOTH', color: '#b787ff', glyph: '✦', hp: 0.92, radius: 27 },
  { name: 'GLASS STAG', color: '#ff9adf', glyph: '♢', hp: 1.35, radius: 32 },
  { name: 'DISCORD SERPENT', color: '#da70ff', glyph: '〰', hp: 0.88, radius: 27 },
  { name: 'BELL JELLY', color: '#ff70ca', glyph: '◉', hp: 1.12, radius: 30 },
];
const comradeSprite = new Image();
comradeSprite.src = 'assets/star-comrade.webp';

// ---------- Data ----------
const TRACKS = [
  {
    title: 'Happy Times',
    file: 'assets/dave-greening-the-midnight-sessions-01-happy-times.mp3',
    story: 'The first recording is almost too bright for this room. Persephone is laughing somewhere beyond the piano, and the player keeps missing notes just to make her laugh again. I wake inside that small, imperfect happiness. He calls me Echo.',
    visual: { kind: 'fireflies', name: 'The first light', tint: '#7f5528', accent: '#ffd782', refrain: 'A little laughter escapes the frame.' },
    boss: 'The First Fret',
  },
  {
    title: 'Long Ago',
    file: 'assets/dave-greening-the-midnight-sessions-02-long-ago.mp3',
    story: 'Years have passed in the space between two chords. The player tells the story as if Persephone were gone forever. I search the recording for proof: a breath, a chair moving, the life that continues after the music stops.',
    visual: { kind: 'memory', name: 'The worn photograph', tint: '#514a63', accent: '#d8c4a1', refrain: 'Time wears a groove, not an ending.' },
    boss: 'The Worn Refrain',
  },
  {
    title: 'Haunted',
    file: 'assets/dave-greening-the-midnight-sessions-03-haunted.mp3',
    story: 'Grief has learned her outline. It crosses the keys like a shadow and fires back every note he cannot bear to remember. This is The Shade—not Persephone, but the fear that her leaving meant she was lost.',
    visual: { kind: 'shadow', name: 'The borrowed silhouette', tint: '#382348', accent: '#c49aff', refrain: 'Grief borrows her face; it is not her.' },
    boss: 'The Shade',
  },
  {
    title: 'Burnt Love Letters',
    file: 'assets/dave-greening-the-midnight-sessions-04-burnt-love-letters.mp3',
    story: 'A letter survives only as ash at the edge of the tape. He wanted an explanation that would make her departure hurt less. The few words left are plain: she loved him, and she needed a life that belonged to her.',
    visual: { kind: 'embers', name: 'The unsent page', tint: '#593323', accent: '#ffb56e', refrain: 'The few words left are plain: loved, and free.' },
    boss: 'The Ashen Letter',
  },
  {
    title: 'Desolation',
    file: 'assets/dave-greening-the-midnight-sessions-05-desolation.mp3',
    story: 'Now the empty room has a name. He mistook silence for an ending and absence for death. I am built from that mistake, a memory looping so faithfully that even I began to believe it.',
    visual: { kind: 'empty', name: 'The room between notes', tint: '#293444', accent: '#b7c5d8', refrain: 'Silence is a room, not a verdict.' },
    boss: 'The Empty Room',
  },
  {
    title: 'Midnight',
    file: 'assets/dave-greening-the-midnight-sessions-06-midnight.mp3',
    story: 'At midnight the old recording clicks, then begins again. Under the piano, a second sound: the hiss of a message left years later. Persephone is alive. Her voice is older, calm, and unmistakably her own.',
    visual: { kind: 'rain', name: 'The message in the rain', tint: '#1c3852', accent: '#93d9ff', refrain: 'A voice arrives from the life beyond the tape.' },
    boss: 'The Rainkeeper',
  },
  {
    title: 'Myriad',
    file: 'assets/dave-greening-the-midnight-sessions-07-myriad.mp3',
    story: 'A thousand versions of her rise from the keys: the girl who stayed, the woman who returned, the ghost he invented. They all speak at once. The Silence waits between them, asking him to choose which story is true.',
    visual: { kind: 'prism', name: 'The many reflections', tint: '#34234f', accent: '#cfb3ff', refrain: 'A thousand versions; one woman, still her own.' },
    boss: 'The Silence',
  },
  {
    title: 'Owls',
    file: 'assets/dave-greening-the-midnight-sessions-08-owls.mp3',
    story: 'Night birds call from the city in her message. Persephone describes a window, rain on the sill, a life that is difficult and hers. She does not ask to be rescued. She only wants him to know she made it safely.',
    visual: { kind: 'owls', name: 'Her window, elsewhere', tint: '#263644', accent: '#d0c5a0', refrain: 'She made a life there, under the same moon.' },
    boss: 'The Night Listener',
  },
  {
    title: 'Simple Waltz',
    file: 'assets/dave-greening-the-midnight-sessions-09-simple-waltz.mp3',
    story: 'He plays their old waltz once more—not to summon her, but to say goodbye without anger. I understand at last: I am not Persephone returned. I am his memory of her, made audible, and a memory can be cherished without being mistaken for a person.',
    visual: { kind: 'waltz', name: 'The last gentle dance', tint: '#4d283c', accent: '#ffb2cf', refrain: 'Let the last dance be a goodbye, not a summons.' },
    boss: 'The Last Dance',
  },
  {
    title: "Persephone's Eternal Sleep",
    file: 'assets/dave-greening-the-midnight-sessions-10-persephones-eternal-sleep.mp3',
    story: 'The title sounds like a tragedy. It is not hers. Persephone did not die; she left. The thing sleeping inside this music is the old recording—and me, Echo, the last bright fragment of a story he can finally let rest or send back into the world.',
    visual: { kind: 'tape', name: 'The last note', tint: '#55463a', accent: '#ffe1aa', refrain: 'An ending is not a death; it is a release.' },
    boss: 'The Last Note',
  },
];

