  const masteryResonance = masteryRanksEarned ? resonanceReward(masteryRanksEarned * 25) : 0;
  if (masteryResonance) save.resonance += masteryResonance;
  if (masteryResonance) run.resonanceEarned += masteryResonance;

  const safePercent = run.ruleActiveSeconds > 0
    ? Math.round(Math.max(0, Math.min(1, run.ruleSafeSeconds / run.ruleActiveSeconds)) * 100)
    : 0;
  const ruleGrade = run.ruleHits > 0 || run.ruleCompletedEvents === 0
    ? 'C'
    : safePercent >= 70
      ? 'S'
      : run.ruleSafeGrazes > 0
        ? 'A'
        : run.ruleCleanEvents > 0
          ? 'B'
          : 'C';
  const ruleBonus = resonanceReward(MEMORY_RULE_RESONANCE[ruleGrade]);
  if (ruleBonus) {
    save.resonance += ruleBonus;
    run.resonanceEarned += ruleBonus;
  }
  const previousRuleRecord = save.memoryMastery[run.track];
  const isNewRuleBest = !previousRuleRecord || MEMORY_RULE_GRADE_RANK[ruleGrade] < MEMORY_RULE_GRADE_RANK[previousRuleRecord.grade];
  const clearDate = new Date().toISOString().slice(0, 10);
  const ruleRecord = {
    grade: isNewRuleBest ? ruleGrade : previousRuleRecord.grade,
    cleanEvents: isNewRuleBest ? run.ruleCleanEvents : previousRuleRecord.cleanEvents,
    events: isNewRuleBest ? run.ruleEvents : previousRuleRecord.events,
    safeGrazes: isNewRuleBest ? run.ruleSafeGrazes : previousRuleRecord.safeGrazes,
    ruleHits: isNewRuleBest ? run.ruleHits : previousRu

