function removeHorizontalSpriteStreaks(image) {
  image.addEventListener('load', () => {
    if (!image.naturalWidth || !image.naturalHeight) return;
    const scratch = document.createElement('canvas');
    scratch.width = image.naturalWidth;
    scratch.height = image.naturalHeight;
    const scratchContext = scratch.getContext('2d', { willReadFrequently: true });
    if (!scratchContext) return;
    scratchContext.drawImage(image, 0, 0);
    let pixels;
    try {
      pixels = scratchContext.getImageData(0, 0, scratch.width, scratch.height);
    } catch (error) {
      return;
    }

    const { data, width, height } = pixels;
    const remove = new Uint8Array(width * height);
    const scanStart = Math.floor(width * 0.58);
    const minRun = Math.max(20, Math.floor(width * 0.045));
    for (let y = 0; y < height; y++) {
      let runStart = -1;
      let baseR = 0;
      let baseG = 0;
      let baseB = 0;
      const finishRun = (end) => {
        if (runStart >= 0 && end - runStart >= minRun) {
          for (let x = runStart; x < end; x++) remove[y * width + x] = 1;
        }
        runStart = -1;
      };
      for (let x = scanStart; x <= width; x++) {
        const offset = (y * width + x) * 4;
        const r = x < width ? data[offset] : 0;
        const g = x < width ? data[offset + 1] : 0;
        const b = x < width ? data[offset + 2] : 0;
        const alpha = x < width ? data[offset + 3] : 0;
        const brightest = Math.max(r, g, b);
        const darkest = Math.min(r, g, b);
        const neutral = x < width && alpha > 18 && brightest - darkest < 38 && brightest > 32 && darkest < 238;
        const matchesRun = neutral && (runStart < 0 || (Math.abs(r - baseR) < 24 && Math.abs(g - baseG) < 24 && Math.abs(b - baseB) < 24));
        if (!matchesRun) {
          finishRun(x);
          if (!neutral) continue;
        }
        if (runStart < 0) {
          runStart = x;
          baseR = r;
          baseG = g;
          baseB = b;
        }
      }
    }
    for (let i = 0; i < remove.length; i++) {
      if (!remove[i]) continue;
      const offset = i * 4;
      data[offset] = 0;
      data[offset + 1] = 0;
      data[offset + 2] = 0;
      data[offset + 3] = 0;
    }
    scratchContext.putImageData(pixels, 0, 0);
    image.src = scratch.toDataURL('image/webp', 0.94);
  }, { once: true });
}

