// The Midnight Sessions: Echoes — vertical bullet-hell
const W = 720;
const H = 1080;
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = W;
canvas.height = H;

function resize() {
  const s = Math.min(window.innerWidth / W, window.innerHeight / H);
  canvas.style.width = `${W * s}px`;
  canvas.style.height = `${H * s}px`;
}
window.addEventListener('resize', resize);
resize();

const SESSION_BACKGROUNDS = [
  'assets/session-bg-happy-times.webp',
  'assets/session-bg-long-ago.webp',
  'assets/session-bg-haunted.webp',
  'assets/session-bg-burnt-letters.webp',
  'assets/session-bg-desolation.webp',
  'assets/session-bg-midnight-rain.webp',
  'assets/session-bg-myriad.webp',
  'assets/session-bg-owls.webp',
  'assets/session-bg-waltz-garden.webp',
  'assets/session-bg-eternal-sleep.webp',
].map((src) => {
  const image = new Image();
  image.src = src;
  return image;
});
const echoSprite = new Image();
echoSprite.src = 'assets/echo-spirit.webp';
const echoAwakenedSprite = new Image();
echoAwakenedSprite.src = 'assets/echo-veil-awakening.webp';
const echoQueenSprite = new Image();
echoQueenSprite.src = 'assets/echo-midnight-queen.webp';
function removeHorizontalSpriteStreaks(image) {
  image.addEventListener('load', () => {
    if (!image.naturalWidth || !image.naturalHeight) return;
    const scratch = document.createElement('canvas');
    scratch.width = image.naturalWidth;
    scratch.height = image.naturalHeight;
    const scratchContext = scratch.getContext('2d', { willReadFrequently: true });
    if (!scratchContext) return;
    scratchContext.drawImage(image, 0, 0);
    let pixels;
    try {
      pixels = scratchContext.getImageData(0, 0, scratch.width, scratch.height);
    } catch (error) {
      return;
    }

    const { data, width, height } = pixels;
    const remove = new Uint8Array(width * height);
    const scanStart = Math.floor(width * 0.58);
    const minRun = Math.max(20, Math.floor(width * 0.045));
    for (let y = 0; y < height; y++) {
      let runStart = -1;
      let baseR = 0;
      let baseG = 0;
      let baseB = 0;
      const finishRun = (end) => {
        if (runStart >= 0 && end - runStart >= minRun) {
          for (let x = runStart; x < end; x++) remove[y * width + x] = 1;
        }
        runStart = -1;
      };
      for (let x = scanStart; x <= width; x++) {
        const offset = (y * width + x) * 4;
        const r = x < width ? data[offset] : 0;
        const g = x < width ? data[offset + 1] : 0;
        const b = x < width ? data[offset + 2] : 0;
        const alpha = x < width ? data[offset + 3] : 0;
        const brightest = Math.max(r, g, b);
        const darkest = Math.min(r, g, b);
        const neutral = x < width && alpha > 18 && brightest - darkest < 38 && brightest > 32 && darkest < 238;
        const matchesRun = neutral && (runStart < 0 || (Math.abs(r - baseR) < 24 && Math.abs(g - baseG) < 24 && Math.abs(b - baseB) < 24));
        if (!matchesRun) {
          finishRun(x);
          if (!neutral) continue;
        }
        if (runStart < 0) {
          runStart = x;
          baseR = r;
          baseG = g;
          baseB = b;
        }
      }
    }
    for (let i = 0; i < remove.length; i++) {
      if (!remove[i]) continue;
      const offset = i * 4;
      data[offset] = 0;
      data[offset + 1] = 0;
      data[offset + 2] = 0;
      data[offset + 3] = 0;
    }
    scratchContext.putImageData(pixels, 0, 0);
    image.src = scratch.toDataURL('image/webp', 0.94);
  }, { once: true });
}

const echoOutfitSprites = {
  rose: new Image(),
  midnight: new Image(),
  frost: new Image(),
};
Object.values(echoOutfitSprites).forEach(removeHorizontalSpriteStreaks);
echoOutfitSprites.rose.src = 'assets/echo-rose-sonata-clean.webp';
echoOutfitSprites.midnight.src = 'assets/echo-midnight-constellation-clean.webp';
echoOutfitSprites.frost.src = 'assets/echo-frosted-songbird-clean.webp';
