    visual: { kind: 'shadow', name: 'The borrowed silhouette', tint: '#382348', accent: '#c49aff', refrain: 'Grief borrows her face; it is not her.' },
    boss: 'The Shade',
  },
  {
    title: 'Burnt Love Letters',
    file: 'assets/dave-greening-the-midnight-sessions-04-burnt-love-letters.mp3',
