    visual: { kind: 'embers', name: 'The unsent page', tint: '#593323', accent: '#ffb56e', refrain: 'The few words left are plain: loved, and free.' },
    boss: 'The Ashen Letter',
  },
  {
    title: 'Desolation',
    file: 'assets/dave-greening-the-midnight-sessions-05-desolation.mp3',
    story: 'Now the empty room has a name. He mistook silence for an ending and absence for death. I am built from that mistake, a memory looping so faithfully that even I began to believe it.',
    visual: { kind: 'empty', name: 'The room between notes', tint: '#293444', accent: '#b7c5d8', refrain: 'Silence is a room, not a verdict.' },
