    visual: { kind: 'rain', name: 'The message in the rain', tint: '#1c3852', accent: '#93d9ff', refrain: 'A voice arrives from the life beyond the tape.' },
    boss: 'The Rainkeeper',
  },
  {
    title: 'Myriad',
    file: 'assets/dave-greening-the-midnight-sessions-07-myriad.mp3',
    story: 'A thousand versions of her rise from the keys: the girl who stayed, the woman who returned, the ghost he invented. They all speak at once. The Silence waits between them, asking him to choose which story is true.',
    visual: { kind: 'prism', name: 'The many reflections', tint: '#34234f', accent: '#cfb3ff', refrain: 'A thousand versions; one woman, still her own.' },
    boss: 'The Silence',
  },
