        {
            action: 'codeError',
            /** @type {ErrorData} */
            content: {
                message: mappedMessage,
                source: mappedSource,
                lineNumber: lineno,
                columnNumber: colno,
                stack: mappedStack,
                errorName: error?.name,
                fullError: error?.toString(),
