import { CARDS, REWARD_POOL, RELICS, ENEMIES, LORE, MYSTERIES } from './data.js';

const TOTAL_STEPS = 15;
const container = document.getElementById('game-container');
const app = document.createElement('main');
app.id = 'app';
app.setAttribute('aria-label', 'Path of the Cluckening game');
container.appendChild(app);

// ---------- Audio ----------
const music = new Audio('assets/audio/tavern-lute.mp3');
music.loop = true;
music.preload = 'auto';
music.volume = Math.max(0, Math.min(1, 0.28));
const hitSfx = new Audio('assets/audio/hit.mp3');
hitSfx.preload = 'auto';
hitSfx.volume = Math.max(0, Math.min(1, 0.5));
let muted = false;
let audioCtx = null;

const muteBtn = document.createElement('button');
muteBtn.id = 'mute';
muteBtn.className = 'btn sound-toggle';
muteBtn.type = 'button';
muteBtn.textContent = '♪';
muteBtn.setAttribute('aria-label', 'Mute sound');
muteBtn.setAttribute('aria-pressed', 'false');
muteBtn.title = 'Sound on';
container.appendChild(muteBtn);
muteBtn.onclick = (event) => {
  event.stopPropagation();
  muted = !muted;
  muteBtn.textContent = muted ? '×' : '♪';
  muteBtn.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound');
  muteBtn.setAttribute('aria-pressed', String(muted));
  muteBtn.title = muted ? 'Sound off' : 'Sound on';
  if (muted) {
    music.pause();
    hitSfx.pause();
    hitSfx.currentTime = 0;
  } else {
    music.play().catch(() => {});
  }
};

function unlockAudio() {
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (AudioContextClass) {
      try {
        audioCtx = new AudioContextClass();
        audioCtx.resume().catch(() => {});
      } catch (error) {
        audioCtx = null;
      }
    }
  }
  if (!muted) music.play().catch(() => {});
}
window.addEventListener('pointerdown', unlockAudio, { once: true });
window.addEventListener('keydown', unlockAudio, { once: true });

function playHit() {
  if (muted) return;
  hitSfx.currentTime = 0;
  hitSfx.play().catch(() => {});
}

function blip(freq = 440) {
  if (muted || !audioCtx) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'square';
  osc.frequency.value = freq;
  gain.gain.setValueAtTime(0.06, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.12);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + 0.12);
}

// ---------- Helpers ----------
const rand = (n) => Math.floor(Math.random() * n);
const pick = (arr) => arr[rand(arr.length)];
const shuffle = (arr) => {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = rand(i + 1);
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
};

function el(tag, cls, html) {
  const node = document.createElement(tag);
  if (cls) node.className = cls;
  if (html !== undefined) node.innerHTML = html;
  return node;
}

function button(label, onClick, sub = '') {
  const b = el('button', 'btn', label + (sub ? `<br><small>${sub}</small>` : ''));
  b.type = 'button';
  b.onclick = () => {
    blip(660);
    onClick();
  };
  return b;
}

// ---------- Run state ----------
let run;

function newRun() {
  run = {
    hp: 70,
    maxHp: 70,
    gold: 30,
    step: 0,
    deck: ['strike', 'strike', 'strike', 'strike', 'strike', 'defend', 'defend', 'defend', 'defend', 'bash'],
    relics: [],
  };
}

function loseHp(amount) {
  run.hp = Math.max(0, run.hp - amount);
}

function hud() {
  const relicNames = run.relics.map((r) => RELICS[r].name).join(', ') || 'none';
  const wrap = el('div');
  wrap.appendChild(el('div', 'hud', `<span>HP ${run.hp}/${run.maxHp}</span><span>${run.gold}g</span><span>Page ${Math.min(run.step + 1, TOTAL_STEPS)}/${TOTAL_STEPS}</span>`));
  wrap.appendChild(el('div', 'hud', `<span>Deck ${run.deck.length} · Relics: ${relicNames}</span>`));
  return wrap;
}

function showPage(title, text, options, allowCollection = false) {
  app.classList.remove('in-battle');
  app.innerHTML = '';
  app.appendChild(hud());
  if (allowCollection) {
    const launch = el('button', 'btn collection-launch', `Deck & Relics <span>${run.deck.length} cards · ${run.relics.length} relics</span>`);
    launch.type = 'button';
    launch.setAttribute('aria-haspopup', 'dialog');
    launch.setAttribute('aria-expanded', 'false');
    launch.setAttribute('aria-controls', 'collection-panel');
    launch.setAttribute('aria-label', `Browse deck of ${run.deck.length} cards and ${run.relics.length} relics`);
    launch.onclick = () => {
      blip(660);
      openCollection(launch);
    };
    app.appendChild(launch);
  }
  const page = el('section', 'page', `<h2 id="page-title" tabindex="-1">${title}</h2>${text}`);
  page.setAttribute('aria-labelledby', 'page-title');
  app.appendChild(page);
  const choices = el('div', 'choices');
  options.forEach((o) => choices.appendChild(button(o.label, o.action, o.sub)));
  app.appendChild(choices);
  page.querySelector('h2').focus({ preventScroll: true });
}

function openCollection(trigger) {
  const overlay = el('div', 'collection-overlay');
  const panel = el('section', 'collection-panel');
  panel.id = 'collection-panel';
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-labelledby', 'collection-title');

  const header = el('header', 'collection-header');
  const heading = el('div');
  const title = el('h2', '', 'Deck & Relics');
  title.id = 'collection-title';
  heading.appendChild(title);
  heading.appendChild(el('p', 'collection-summary', `${run.deck.length} cards · ${run.relics.length}/${Object.keys(RELICS).length} relics found`));
  const close = el('button', 'btn collection-close', '×');
  close.type = 'button';
  close.setAttribute('aria-label', 'Close Deck and Relics');
  header.append(heading, close);
  panel.appendChild(header);

  const content = el('div', 'collection-scroll');
  const cardSection = el('section', 'collection-section');
  cardSection.appendChild(el('h3', '', 'Cards in your pack'));
  cardSection.appendChild(el('p', 'collection-hint', 'Counts show how many copies you carry.'));
  const cardList = el('div', 'collection-list');
  const cardCounts = run.deck.reduce((counts, id) => {
    counts[id] = (counts[id] || 0) + 1;
    return counts;
  }, {});
  Object.entries(CARDS).forEach(([id, card]) => {
    const row = el('article', 'collection-entry');
    const nameLine = el('div', 'collection-entry-heading');
    nameLine.appendChild(el('strong', '', card.name));
    nameLine.appendChild(el('span', 'collection-count', `× ${cardCounts[id] || 0}`));
    row.appendChild(nameLine);
    row.appendChild(el('p', 'collection-detail', `${card.unplayable ? 'Unplayable' : `Cost ${card.cost}`} · ${card.text}`));
    cardList.appendChild(row);
  });
  cardSection.appendChild(cardList);
  content.appendChild(cardSection);

  const relicSection = el('section', 'collection-section');
  relicSection.appendChild(el('h3', '', 'Relics & effects'));
  const relicList = el('div', 'collection-list');
  Object.entries(RELICS).forEach(([id, relic]) => {
    const owned = run.relics.includes(id);
    const row = el('article', `collection-entry relic-entry${owned ? ' is-owned' : ''}`);
    const nameLine = el('div', 'collection-entry-heading');
    nameLine.appendChild(el('strong', '', relic.name));
    nameLine.appendChild(el('span', `relic-status${owned ? ' is-owned' : ''}`, owned ? 'Owned' : 'Not found'));
    row.appendChild(nameLine);
    row.appendChild(el('p', 'collection-detail', relic.text));
    relicList.appendChild(row);
  });
  relicSection.appendChild(relicList);
  content.appendChild(relicSection);
  panel.appendChild(content);
  overlay.appendChild(panel);

  function closeCollection() {
    overlay.remove();
    trigger.setAttribute('aria-expanded', 'false');
    if (trigger.isConnected) trigger.focus({ preventScroll: true });
  }

  close.onclick = closeCollection;
  overlay.addEventListener('click', (event) => {
    if (event.target === overlay) closeCollection();
  });
  overlay.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      event.preventDefault();
      closeCollection();
    } else if (event.key === 'Tab') {
      event.preventDefault();
      close.focus();
    }
  });
  trigger.setAttribute('aria-expanded', 'true');
  app.appendChild(overlay);
  close.focus({ preventScroll: true });
}

// ---------- Title / end ----------
function titleScreen() {
  newRun();
  showPage('PATH OF THE CLUCKENING',
    'One hero. One deck. Fifteen pages of peril.<br><br>Choose your road, build your deck, and survive the trek to the Chicken Monster at the Roost.<br><br>Death is final. Every run starts fresh.',
    [{ label: 'Begin the Tale', action: nextPage }]);
}

function endScreen(won) {
  showPage(won ? 'VICTORY!' : 'YOU HAVE FALLEN',
    won ? 'The Cluckening falls with a final, earth-shaking squawk. Embervale wakes. Your legend is written... and the book closes.'
      : run.step >= TOTAL_STEPS ? 'Your tale ends at the Roost. The feathers settle over your bones.' : `Your tale ends on page ${run.step + 1}. The feathers settle over your bones.`, 
    [{ label: 'Start a New Run', action: titleScreen }]);
}

// ---------- Map / choices ----------
function nextPage() {
  if (run.step >= TOTAL_STEPS) {
    showPage('The Roost', 'A mountain of bones and straw. Above it, a shape blots out the sky. It CLUCKS.',
      [{ label: 'Face the Cluckening', action: () => startBattle('boss') }]);
    return;
  }
  const lore = run.step % 3 === 0 ? `<i>${LORE[Math.min(run.step / 3, LORE.length - 1)]}</i><br><br>` : '';
  const types = shuffle(['battle', 'battle', 'mystery', 'treasure', 'shrine', 'elite']).slice(0, 3);
  const desc = {
    battle: ['A dark path', 'Monsters lurk. Card reward.'],
    elite: ['A blood-stained trail', 'Tough foe. Relic reward.'],
    mystery: ['A misty path', 'Something strange awaits.'],
    treasure: ['A glittering path', 'Gold... maybe a trap.'],
    shrine: ['A quiet campfire', 'Rest or train.'],
  };
  showPage(`Page ${run.step + 1}`, `${lore}The road forks. Which way?`,
    types.map((t) => ({ label: desc[t][0], sub: desc[t][1], action: () => resolve(t) })), true);
}

function advance() {
  run.step++;
  nextPage();
}

function resolve(type) {
  if (type === 'battle') {
    const pool = run.step < 5 ? ['slime', 'goblin'] : ['goblin', 'skeleton', 'wolf'];
    startBattle(pick(pool));
  } else if (type === 'elite') {
    startBattle(run.step < 6 ? 'skeleton' : 'wolf', true);
  } else if (type === 'mystery') {
    mystery();
  } else if (type === 'treasure') {
    treasure();
  } else {
    shrine();
  }
}

function result(title, text) {
  if (run.hp <= 0) {
    endScreen(false);
    return;
  }
  showPage(title, text, [{ label: 'Continue', action: advance }]);
}

function treasure() {
  if (Math.random() < 0.25) {
    loseHp(8);
    run.gold += 25;
    result('Mimic!', 'The chest bites! You lose 8 HP but pry out 25 gold.');
    return;
  }
  const free = Object.keys(RELICS).filter((r) => !run.relics.includes(r));
  if (free.length && Math.random() < 0.5) {
    const relic = pick(free);
    gainRelic(relic);
    result('Treasure!', `You find the <b>${RELICS[relic].name}</b>: ${RELICS[relic].text}.`);
  } else {
    run.gold += 40;
    result('Treasure!', 'A pouch of 40 gold coins.');
  }
}

function gainRelic(relic) {
  run.relics.push(relic);
  if (relic === 'chalice') {
    run.maxHp += 5;
  }
}

function shrine() {
  const options = [
    { label: 'Rest', sub: 'Heal 30% HP', action: () => { run.hp = Math.min(run.maxHp, run.hp + Math.round(run.maxHp * 0.3)); result('Rested', 'The fire warms your bones.'); } },
    { label: 'Train', sub: 'Remove a card', action: () => removeCard() },
  ];
  if (run.gold >= 50) {
    options.push({ label: 'Merchant (50g)', sub: 'Buy a card', action: () => { run.gold -= 50; cardReward(); } });
  }
  showPage('Campfire', 'A traveling merchant shares your fire.', options);
}

function removeCard() {
  const unique = [...new Set(run.deck)];
  showPage('Remove a card', 'Choose a card to forget.',
    unique.map((id) => ({ label: CARDS[id].name, sub: CARDS[id].text, action: () => {
      run.deck.splice(run.deck.indexOf(id), 1);
      result('Lighter mind', `${CARDS[id].name} removed.`);
    } })));
}

function mystery() {
  const m = pick(MYSTERIES);
  showPage(m.title, m.text, m.options.map((o) => ({ label: o.label, action: () => mysteryOutcome(o.outcome) })));
}

function mysteryOutcome(outcome) {
  switch (outcome) {
    case 'gamble':
      if (Math.random() < 0.5) {
        run.gold += 50;
        result('Lucky!', 'You pull up 50 gold!');
      } else {
        loseHp(10);
        result('Bitten!', 'Something bites. Lose 10 HP.');
      }
      break;
    case 'wellCoin':
      if (run.gold >= 10) {
        run.gold -= 10;
        run.maxHp += 6;
        run.hp += 6;
        result('Blessed', 'Max HP +6.');
      } else {
        result('Broke', 'You have no coin. The well sighs.');
      }
      break;
    case 'darkPact':
      run.deck.push('smite', 'curse');
      result('Dark Pact', 'Smite and a Cursed Feather join your deck.');
      break;
    case 'smash':
      loseHp(6);
      run.gold += 40;
      result('Smashed', 'Bones fly. -6 HP, +40 gold.');
      break;
    case 'remove':
      removeCard();
      break;
    case 'heal15':
      run.hp = Math.min(run.maxHp, run.hp + 15);
      result('Blessing', 'Heal 15.');
      break;
    case 'egg':
      if (Math.random() < 0.5) {
        run.deck.push('flurry');
        result('Hatchling Gift', 'A golden chick leaves you Flurry!');
      } else {
        startBattle('slime');
      }
      break;
    default:
      result('Onward', 'You leave it be.');
  }
}

function cardReward() {
  const options = shuffle([...REWARD_POOL]).slice(0, 3);
  showPage('Choose a card', 'Add one card to your deck.', [
    ...options.map((id) => ({ label: `${CARDS[id].name} (${CARDS[id].cost})`, sub: CARDS[id].text, action: () => { run.deck.push(id); advance(); } })),
    { label: 'Skip', action: advance },
  ]);
}

// ---------- Battle ----------
let battle;

function startBattle(enemyId, elite = false) {
  const def = ENEMIES[enemyId];
  const scale = enemyId === 'boss' ? 1 : 1 + run.step * 0.014 + (elite ? 0.35 : 0);
  battle = {
    id: enemyId,
    elite,
    enemy: { ...def, hp: Math.round(def.hp * scale), maxHp: Math.round(def.hp * scale), block: 0, str: 0, weak: 0, turn: 0 },
    draw: shuffle([...run.deck]),
    discard: [],
    hand: [],
    block: run.relics.includes('amulet') ? 6 : 0,
    energy: 3,
    log: [],
    resolving: false,
  };
  logBattle(`Battle begins · ${def.name}`, 'start');
  logBattle(`Intent · ${intentText()}`, 'intent');
  startTurn();
}

function startTurn() {
  battle.energy = 3;
  const count = 5 + (run.relics.includes('boots') ? 1 : 0);
  const handBefore = battle.hand.length;
  drawCards(count);
  const drawn = battle.hand.length - handBefore;
  const curses = battle.hand.filter((id) => id === 'curse').length;
  logBattle(`Turn ${battle.enemy.turn + 1} · ${drawn} cards drawn${curses ? ` · ${curses} Curse in hand` : ''}`, 'turn');
  renderBattle();
}

function drawCards(n) {
  for (let i = 0; i < n; i++) {
    if (!battle.draw.length) {
      battle.draw = shuffle(battle.discard);
      battle.discard = [];
    }
    if (!battle.draw.length) return;
    battle.hand.push(battle.draw.pop());
  }
}

function intent() {
  const e = battle.enemy;
  return e.pattern[e.turn % e.pattern.length];
}

function intentText() {
  const i = intent();
  const e = battle.enemy;
  const parts = [];
  if (i.atk) {
    const hits = i.hits || 1;
    const raw = i.atk + e.str;
    const damage = e.weak > 0 ? Math.floor(raw * 0.75) : raw;
    parts.push(`Attack ${damage}${hits > 1 ? ` × ${hits} (${damage * hits} total)` : ''}${e.weak > 0 ? ' (Weak)' : ''}`);
  }
  if (i.block) parts.push(`Gain ${i.block} Block`);
  if (i.buff) parts.push(`Gain +${i.buff} Strength`);
  if (i.curse) parts.push('Add Curse to discard');
  return parts.join(' · ') || 'Wait';
}

function logBattle(message, type = 'event') {
  if (!battle) return;
  battle.log.unshift({ message, type });
  if (battle.log.length > 12) battle.log.length = 12;
}

function combatStatus() {
  const e = battle.enemy;
  const status = el('section', 'combat-status');
  status.setAttribute('aria-label', 'Combat status');
  const addChip = (label, value, className = '', accessibleValue = value) => {
    const chip = el('div', `combat-chip${className ? ` ${className}` : ''}`);
    chip.setAttribute('aria-label', `${label}: ${accessibleValue}`);
    chip.appendChild(el('span', 'combat-chip-label', label));
    chip.appendChild(el('strong', 'combat-chip-value', value));
    status.appendChild(chip);
  };
  addChip('HERO BLOCK', battle.block, 'is-block');
  addChip('ENEMY BLOCK', e.block, 'is-block');
  addChip('ENEMY STR', `+${e.str}`, 'is-strength');
  addChip('ENEMY WEAK', e.weak, 'is-weak', `${e.weak} turns`);
  const handCurses = battle.hand.filter((id) => id === 'curse').length;
  const drawCurses = battle.draw.filter((id) => id === 'curse').length;
  const discardCurses = battle.discard.filter((id) => id === 'curse').length;
  addChip('CURSES · HAND / DRAW / DISCARD', `${handCurses} / ${drawCurses} / ${discardCurses}`, 'is-curse', `${handCurses} in hand, ${drawCurses} in draw pile, ${discardCurses} in discard pile`);
  return status;
}

function combatLog() {
  const section = el('section', 'combat-log');
  section.setAttribute('aria-label', 'Recent combat events');
  section.appendChild(el('h3', 'combat-log-heading', 'TURN LOG · NEWEST FIRST'));
  const list = el('ol', 'combat-log-list');
  list.setAttribute('aria-live', 'polite');
  list.setAttribute('aria-relevant', 'additions text');
  battle.log.slice(0, 4).forEach((entry, index) => {
    const item = el('li', `combat-log-entry combat-log--${entry.type}`, entry.message);
    if (index === 0) item.setAttribute('aria-current', 'true');
    list.appendChild(item);
  });
  section.appendChild(list);
  return section;
}

function floatText(target, text) {
  const node = document.querySelector(target);
  if (!node) return;
  node.classList.add('shake');
  const f = el('div', 'float', text);
  node.appendChild(f);
  setTimeout(() => node.classList.remove('shake'), 300);
}

function healthMeter(label, hp, maxHp) {
  const bar = el('div', 'bar');
  bar.setAttribute('role', 'meter');
  bar.setAttribute('aria-label', `${label} health`);
  bar.setAttribute('aria-valuemin', '0');
  bar.setAttribute('aria-valuemax', String(maxHp));
  bar.setAttribute('aria-valuenow', String(Math.max(0, hp)));
  const fill = el('div');
  fill.style.width = `${Math.max(0, Math.min(100, (hp / maxHp) * 100))}%`;
  bar.appendChild(fill);
  return bar;
}

function createUnit(label, image, hp, maxHp, kind) {
  const unit = el('div', `unit ${kind}`);
  const portrait = el('img');
  portrait.src = `assets/${image}.webp`;
  portrait.alt = `${label} portrait`;
  portrait.decoding = 'async';
  unit.appendChild(portrait);
  unit.appendChild(el('div', 'unit-name', label));
  unit.appendChild(healthMeter(label, hp, maxHp));
  unit.appendChild(el('div', 'unit-hp', `HP ${Math.max(0, hp)}/${maxHp}`));
  return unit;
}

function renderBattle() {
  const e = battle.enemy;
  app.classList.add('in-battle');
  app.innerHTML = '';
  app.appendChild(hud());
  const arena = el('div', 'arena');
  arena.appendChild(createUnit('Hero', 'hero', run.hp, run.maxHp, 'hero-unit'));
  const enemyLabel = battle.elite ? `${e.name} · ELITE` : battle.id === 'boss' ? `${e.name} · BOSS` : e.name;
  arena.appendChild(createUnit(enemyLabel, e.img, e.hp, e.maxHp, 'enemy-unit'));
  app.appendChild(arena);
  const intentStrip = el('div', 'intent', `NEXT INTENT · ${intentText()}`);
  intentStrip.setAttribute('aria-live', 'polite');
  intentStrip.setAttribute('aria-label', `Next enemy intent: ${intentText()}`);
  app.appendChild(intentStrip);
  const combatInfo = el('div', 'combat-info');
  combatInfo.appendChild(combatStatus());
  combatInfo.appendChild(el('div', 'row combat-resources', `<span>⚡ ${battle.energy}/3 Energy</span><span>Draw ${battle.draw.length} · Disc ${battle.discard.length}</span>`));
  combatInfo.appendChild(combatLog());
  app.appendChild(combatInfo);
  const hand = el('div', 'hand');
  battle.hand.forEach((id, index) => {
    const c = CARDS[id];
    const card = el('button', `card card--${c.art}`, `<span class="card-art-wrap"><img class="card-art" src="assets/card-art-${c.art}.webp" alt="" draggable="false"></span><span class="cost">${c.unplayable ? '-' : c.cost}</span><b>${c.name}</b><span class="card-description">${c.text}</span>`);
    card.setAttribute('aria-label', `${c.name}, ${c.unplayable ? 'unplayable' : `${c.cost} energy`}. ${c.text}`);
    card.disabled = battle.resolving || c.unplayable || c.cost > battle.energy;
    card.onclick = () => playCard(index);
    hand.appendChild(card);
  });
  app.appendChild(hand);
  const endBtn = button('End Turn', endTurn);
  endBtn.style.textAlign = 'center';
  endBtn.disabled = battle.resolving;
  app.appendChild(endBtn);
}

function damageEnemy(amount) {
  const e = battle.enemy;
  let dmg = amount + (run.relics.includes('ring') ? 1 : 0);
  const absorbed = Math.min(e.block, dmg);
  e.block -= absorbed;
  dmg -= absorbed;
  const hpDamage = Math.min(Math.max(0, e.hp), dmg);
  e.hp = Math.max(0, e.hp - hpDamage);
  return hpDamage;
}

function playCard(index) {
  if (!battle || battle.resolving || index < 0 || index >= battle.hand.length) return;
  const id = battle.hand[index];
  const c = CARDS[id];
  battle.energy -= c.cost;
  battle.hand.splice(index, 1);
  battle.discard.push(id);
  const effects = [];
  let dealt = 0;
  let enemyBlockSpent = 0;
  if (c.dmg) {
    const blockBefore = battle.enemy.block;
    for (let h = 0; h < (c.hits || 1) && battle.enemy.hp > 0; h++) {
      dealt += damageEnemy(c.dmg);
    }
    enemyBlockSpent = blockBefore - battle.enemy.block;
    effects.push(`${dealt} HP damage${enemyBlockSpent ? ` · ${enemyBlockSpent} enemy Block broken` : ''}`);
    playHit();
  }
  if (c.block) {
    battle.block += c.block;
    effects.push(`Block +${c.block}`);
  }
  if (c.weak) {
    battle.enemy.weak += c.weak;
    effects.push(`Weak +${c.weak} (${battle.enemy.weak} total)`);
  }
  if (c.heal) {
    const hpBefore = run.hp;
    run.hp = Math.min(run.maxHp, run.hp + c.heal);
    effects.push(`Heal +${run.hp - hpBefore}`);
  }
  if (c.energy) {
    battle.energy += c.energy;
    effects.push(`Energy +${c.energy}`);
  }
  if (c.selfDmg) {
    loseHp(c.selfDmg);
    effects.push(`Self-damage ${c.selfDmg}`);
  }
  if (c.draw) {
    const handBefore = battle.hand.length;
    drawCards(c.draw);
    effects.push(`Draw ${battle.hand.length - handBefore}`);
  }
  if (!c.dmg) blip(300);
  logBattle(`${c.name} · ${effects.join(' · ') || 'No immediate effect'}`, 'player');
  const battleEnded = checkBattleEnd();
  renderBattle();
  if (c.dmg) floatText('.enemy-unit', `-${dealt}`);
  if (battleEnded) return;
}

function checkBattleEnd() {
  if (battle.resolving) return true;
  if (run.hp <= 0) {
    battle.resolving = true;
    setTimeout(() => endScreen(false), 600);
    return true;
  }
  if (battle.enemy.hp <= 0) {
    battle.resolving = true;
    setTimeout(winBattle, 600);
    return true;
  }
  return false;
}

function endTurn() {
  if (!battle || battle.resolving) return;
  const e = battle.enemy;
  const handCurses = battle.hand.filter((id) => id === 'curse').length;
  battle.discard.push(...battle.hand);
  battle.hand = [];
  const enemyBlockFaded = e.block;
  e.block = 0;
  const i = intent();
  let taken = 0;
  let incoming = 0;
  let blocked = 0;
  if (i.atk) {
    let dmg = i.atk + e.str;
    if (e.weak > 0) dmg = Math.floor(dmg * 0.75);
    for (let h = 0; h < (i.hits || 1); h++) {
      incoming += dmg;
      const absorbed = Math.min(battle.block, dmg);
      battle.block -= absorbed;
      blocked += absorbed;
      loseHp(dmg - absorbed);
      taken += dmg - absorbed;
    }
  }
  if (i.block) e.block += i.block;
  if (i.buff) e.str += i.buff;
  if (i.curse) battle.discard.push('curse');
  const weakBefore = e.weak;
  if (e.weak > 0) e.weak--;
  e.turn++;
  const playerBlockFaded = battle.block;
  battle.block = 0;

  if (taken) playHit();
  if (i.atk) logBattle(`Enemy attack · ${incoming} incoming · ${taken} HP lost · ${blocked} Block absorbed`, 'enemy');
  const changes = [];
  if (enemyBlockFaded) changes.push(`Enemy Block ${enemyBlockFaded} expired`);
  if (i.block) changes.push(`Enemy Block +${i.block}`);
  if (i.buff) changes.push(`Enemy Strength +${i.buff} (${e.str})`);
  if (i.curse) changes.push('Curse added to discard');
  if (handCurses) changes.push(`${handCurses} Curse discarded from hand`);
  if (weakBefore) changes.push(e.weak ? `Enemy Weak ${weakBefore} → ${e.weak}` : 'Enemy Weak expires');
  if (playerBlockFaded) changes.push(`Your remaining ${playerBlockFaded} Block fades`);
  if (changes.length) logBattle(changes.join(' · '), 'status');
  logBattle(`Next intent · ${intentText()}`, 'intent');

  if (checkBattleEnd()) {
    renderBattle();
    return;
  }
  startTurn();
  if (taken) floatText('.hero-unit', `-${taken}`);
}

function winBattle() {
  if (battle.id === 'boss') {
    endScreen(true);
    return;
  }
  const gold = 15 + rand(15) + (battle.elite ? 25 : 0);
  run.gold += gold;
  if (run.relics.includes('chalice')) {
    run.hp = Math.min(run.maxHp, run.hp + 6);
  }
  let text = `Victory! +${gold} gold.`;
  if (battle.elite) {
    const free = Object.keys(RELICS).filter((r) => !run.relics.includes(r));
    if (free.length) {
      const relic = pick(free);
      gainRelic(relic);
      text += `<br>Relic: <b>${RELICS[relic].name}</b> — ${RELICS[relic].text}`;
    }
  }
  showPage('Battle Won', text, [{ label: 'Claim card reward', action: cardReward }]);
}

titleScreen();

