function isTrustedRosebudParentOrigin(origin) {
    try {
        const url = new URL(origin);
        const isRosebudHost = url.hostname === 'rosebud.ai' || url.hostname.endsWith('.rosebud.ai');
        const isLocalHost = ['localhost', '127.0.0.1', 'rosebudlocal.com'].includes(url.hostname);
        return (
            (isRosebudHost && url.protocol === 'https:') ||
            (isLocalHost && ['http:', 'https:'].includes(url.protocol) && url.port === '5170')
        );
    } catch (_error) {
        return false;
    }
}

function getTrustedRosebudParentOrigin(referrer) {
    try {
        const origin = new URL(referrer).origin;
        return isTrustedRosebudParentOrigin(origin) ? origin : null;
    } catch (_error) {
        return null;
    }
}

function snapshotLocalStorage(storage) {
    const snapshot = {};

    for (let index = 0; index < storage.length; index += 1) {
        const key = storage.key(index);
        if (key !== null) snapshot[key] = storage.getItem(key);
    }

    return snapshot;
}

function initializeLocalStorageBridge() {
    if (window.__rosebudLocalStorageBridgeInitialized) return;
    if (new URLSearchParams(window.location.search).get('embed') !== 'ios') return;

    const trustedParentOrigin = getTrustedRosebudParentOrigin(document.referrer);
    if (!trustedParentOrigin || window.parent === window) return;

    const originalLocalStorage = window.localStorage;
    if (!originalLocalStorage) return;

    function notifyParent() {
        window.parent.postMessage(
            {
                action: 'localStorageChanged',
                content: snapshotLocalStorage(originalLocalStorage),
            },
            trustedParentOrigin,
        );
    }

    const bridgedLocalStorage = new Proxy(originalLocalStorage, {
        get(target, property) {
            const value = Reflect.get(target, property, target);
            if (typeof value !== 'function') return value;

            return (...args) => {
                const result = value.apply(target, args);
                if (['setItem', 'removeItem', 'clear'].includes(property)) notifyParent();
                return result;
            };
        },
        set(target, property, value) {
            const result = Reflect.set(target, property, value, target);
            notifyParent();
            return result;
        },
        deleteProperty(target, property) {
            target.removeItem(property);
            notifyParent();
            return true;
        },
    });

    Object.defineProperty(window, 'localStorage', {
        configurable: false,
        get: () => bridgedLocalStorage,
        set: () => console.warn('Attempt to overwrite localStorage blocked'),
    });

    window.addEventListener('message', (event) => {
        if (
            event.source !== window.parent ||
            event.origin !== trustedParentOrigin ||
            event.data?.action !== 'setLocalStorage' ||
            typeof event.data.data !== 'object' ||
            event.data.data === null ||
            Array.isArray(event.data.data)
